def split_information(left_labels, right_labels):
    n = len(left_labels) + len(right_labels)
    p_left = len(left_labels) / n
    p_right = len(right_labels) / n
    return -(p_left * np.log2(p_left) + p_right * np.log2(p_right))

def gain_ratio(parent, left, right):
    ig = information_gain(parent, left, right)
    si = split_information(left, right)
    return ig / si if si > 0 else 0
